import{_ as s,o as a,c as t,ao as i}from"./chunks/framework.DAbzcW3k.js";const u=JSON.parse('{"title":"Faster startup","description":"","frontmatter":{},"headers":[],"relativePath":"startup.md","filePath":"startup.md","lastUpdated":null}'),l={name:"startup.md"};function r(p,e,o,n,h,d){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="Faster-startup" tabindex="-1">Faster startup <a class="header-anchor" href="#Faster-startup" aria-label="Permalink to &quot;Faster startup {#Faster-startup}&quot;">​</a></h1><p>Why is the first start slow? Julia compiles the code before it runs it. A system image (sysimage) keeps the compiled code in a file, so Julia does not compile it again.</p><p>Build the sysimage one time. This can take 10 minutes or more:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build_sysimage.jl</span></span></code></pre></div><p>Then start TerraScope with the sysimage:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -J</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/TerraScopeSysimage.dll</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/launch_TerraScope3D.jl</span></span></code></pre></div><p>The <code>-J</code> option tells Julia which sysimage to use.</p><p>The sysimage removes most of the compile time. It does not remove the time to read files, to set up the display or to start the graphics. But the startup time becomes shorter and more regular.</p><p>Build the sysimage again after you update TerraScope or its packages.</p><h2 id="Windows-launcher" tabindex="-1">Windows launcher <a class="header-anchor" href="#Windows-launcher" aria-label="Permalink to &quot;Windows launcher {#Windows-launcher}&quot;">​</a></h2><p>On Windows, double-click <code>Launch-TerraScope.cmd</code> in the repository folder, or run it from a terminal:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Launch-TerraScope.cmd</span></span></code></pre></div><p>If the sysimage is available, the launcher uses it. If not, the launcher asks you to build it.</p>',13)])])}const m=s(l,[["render",r]]);export{u as __pageData,m as default};
